"use strict";

const http = require("node:http");

function readText(res) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    res.setEncoding("utf8");
    res.on("data", (chunk) => chunks.push(chunk));
    res.on("end", () => resolve(chunks.join("")));
    res.on("error", reject);
  });
}

function resolveRedirect(baseUrl, location) {
  return new URL(location, baseUrl).toString();
}

function requestOnce(url, depth) {
  return new Promise((resolve, reject) => {
    const req = http.get(url, { timeout: 1000 }, async (res) => {
      try {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          res.resume();
          if (depth <= 0) {
            reject(new Error("redirect limit exceeded"));
            return;
          }
          resolve(requestOnce(resolveRedirect(url, res.headers.location), depth - 1));
          return;
        }
        const body = await readText(res);
        resolve([
          "httpnpm.redirect-follow=" + res.statusCode,
          res.statusMessage,
          res.headers["x-path"],
          body,
        ].join("|"));
      } catch (error) {
        reject(error);
      }
    });
    req.on("error", reject);
  });
}

exports.get = function get(url) {
  return requestOnce(url, 3);
};
